package runtime

// Observational equivalence (paper §3.3.2, Definitions 31-35) — runtime-bound.
//
// The relation is DERIVED FROM THE OPERATIONS a key actually supports, not
// hand-declared fields and not an ad-hoc string canonicalization:
//
//   - Def 29: a key carries an operation set 𝒜ₖ; each operation reads/writes
//     only that key's binding (lift eq.31). What an observer can distinguish at
//     a key is exactly what those operations can reach.
//   - Def 31/32: ≃ₖ is generated by finite tests over 𝒜ₖ — the COARSEST
//     equivalence every operation respects. We realize this by mapping each
//     operation to the provider fields it observes; a key's ≃ₖ compares the
//     union of fields its declared operations can reach.
//   - Def 33: σ ≃_S σ' ≔ dom(σ)∩S = dom(σ')∩S ∧ ∀k∈dom∩S. σ(k) ≃ₖ σ'(k).
//     Critically, a "binding" here is (key, realm) — paper Def 24 allows the
//     SAME key in MULTIPLE realms, and ProviderView carries ScopeID. Merging
//     providers by key alone would conflate distinct bindings (audit R1).
//
// Default policy (audit R2): a key with NO declared OperationSet is treated as
// supporting ALL real runtime operations — because the runtime genuinely does
// provide/require, bind ProviderIdentity (Thm 70), and route through realms
// (Def 24/Rehome). We never silently weaken an undeclared key to an
// availability-only view; that would erase observable identity/realm changes.

import (
	"fmt"
	"sort"
)

// ObservedField is one provider-record facet that some operation can reach.
type ObservedField string

const (
	// ObserveAvailability — whether the binding is satisfiable (State+Retiring).
	// Reached by provide/require operations.
	ObserveAvailability ObservedField = "availability"
	// ObserveOwnerGeneration — which Fiber/Activation owns the binding.
	// Reached by dependency capture/withdrawal (Thm 70) and Revise (Thm 80).
	ObserveOwnerGeneration ObservedField = "owner-generation"
	// ObserveNamespace — which realm (ScopeID) binds the key (Def 24 ρ).
	// Reached by Isolate/Rehome and isolation conformance checks.
	ObserveNamespace ObservedField = "namespace"
)

// Operation is a real runtime operation a key supports (paper Def 29 𝒜ₖ).
type Operation string

const (
	OpProvide       Operation = "provide"
	OpRequire       Operation = "require"
	OpProvideMeta   Operation = "provide-meta"
	OpRequireMeta   Operation = "require-meta"
	OpInterceptMeta Operation = "intercept-meta"
	// OpBindIdentity models dependency capture/withdrawal reading the provider
	// identity (ProvideMeta/RequireMeta evaluations carry it in deps snapshots).
	OpBindIdentity Operation = "bind-identity"
	// OpRealmRoute models isolation/rehome reading the per-key realm (ρ).
	OpRealmRoute Operation = "realm-route"
)

// operationFields maps an operation to the fields it can observe. This is the
// R2 fix: observation boundaries are derived from operations, not declared
// independently — an OperationSet that declares OpRequire but omits
// ObserveAvailability is rejected by Validate (see below).
func operationFields(op Operation) map[ObservedField]bool {
	switch op {
	case OpProvide, OpRequire:
		return map[ObservedField]bool{ObserveAvailability: true}
	case OpProvideMeta, OpRequireMeta, OpInterceptMeta:
		return map[ObservedField]bool{ObserveAvailability: true, ObserveOwnerGeneration: true}
	case OpBindIdentity:
		return map[ObservedField]bool{ObserveOwnerGeneration: true}
	case OpRealmRoute:
		return map[ObservedField]bool{ObserveNamespace: true}
	default:
		return map[ObservedField]bool{}
	}
}

// OperationSet is the operations a key actually supports (paper Def 29 𝒜ₖ).
type OperationSet struct {
	Key CapabilityKey
	Ops []Operation
}

// ObservationSpec declares which operations a key supports. The observed
// fields are DERIVED from Ops via operationFields — callers cannot declare
// fields directly (R2). A spec with no ops is invalid (Validate rejects it).
type ObservationSpec struct {
	Key CapabilityKey
	Ops []Operation
}

// ObservationModel is key → operation set. The model is immutable after build.
type ObservationModel struct {
	ops     map[CapabilityKey][]Operation
	invalid bool // set by NewObservationModel when a spec is malformed
}

// NewObservationModel builds a model from explicit operation declarations.
// An empty spec list means "no key opted into a restricted view" — all keys
// use the conservative default (all real operations).
func NewObservationModel(specs ...ObservationSpec) *ObservationModel {
	m := &ObservationModel{ops: make(map[CapabilityKey][]Operation, len(specs))}
	for _, s := range specs {
		m.ops[s.Key] = append([]Operation(nil), s.Ops...)
	}
	// Fail closed: a malformed spec must never enter a comparison. Validate
	// is called at build time; invalid models make all equivalences FALSE.
	if err := m.Validate(); err != nil {
		m.invalid = true
	}
	return m
}

// OperationsFor returns the operations observed at key. The default is ALL
// real operations (R2: never silently weaken an undeclared key).
func (m *ObservationModel) OperationsFor(k CapabilityKey) []Operation {
	if m != nil {
		if ops, ok := m.ops[k]; ok {
			return ops
		}
	}
	return []Operation{
		OpProvide, OpRequire, OpProvideMeta, OpRequireMeta,
		OpInterceptMeta, OpBindIdentity, OpRealmRoute,
	}
}

// Validate checks that a spec's operations are known and non-empty. It is the
// guard that keeps observation boundaries tied to real operations (R2): a
// misspelled or empty operation set cannot pass as a "restricted view".
func (m *ObservationModel) Validate() error {
	for k, ops := range m.ops {
		if len(ops) == 0 {
			return &ObservationSpecError{Key: k, Reason: "empty operation set — a key must declare at least one real operation"}
		}
		for _, op := range ops {
			switch op {
			case OpProvide, OpRequire, OpProvideMeta, OpRequireMeta,
				OpInterceptMeta, OpBindIdentity, OpRealmRoute:
			default:
				return &ObservationSpecError{Key: k, Reason: "unknown operation " + string(op)}
			}
		}
	}
	return nil
}

type ObservationSpecError struct {
	Key    CapabilityKey
	Reason string
}

func (e *ObservationSpecError) Error() string {
	return "observation spec for " + e.Key.String() + ": " + e.Reason
}

// fieldsFor derives the observation boundary from the key's operations.
func (m *ObservationModel) fieldsFor(k CapabilityKey) map[ObservedField]bool {
	f := map[ObservedField]bool{}
	for _, op := range m.OperationsFor(k) {
		for field := range operationFields(op) {
			f[field] = true
		}
	}
	return f
}

// BindingID is the identity of one provider binding: (key, realm). Two realms
// providing the same key are TWO distinct bindings (R1 / paper Def 24).
type BindingID struct {
	// Key is the snapshot string form of the capability (ProviderView.Key).
	Key   string
	Scope ScopeID
}

// ObservableBindings returns all provider bindings in scope S, sorted, with
// (key, realm) as identity — no key-only dedup (R1). S == nil means all keys.
func ObservableBindings(o RuntimeSnapshot, S []CapabilityKey) []BindingID {
	var filter map[string]bool
	if S != nil {
		filter = make(map[string]bool, len(S))
		for _, k := range S {
			filter[k.String()] = true
		}
	}
	seen := map[BindingID]bool{}
	var out []BindingID
	for _, p := range o.Providers {
		k := p.Key
		if filter != nil && !filter[k] {
			continue
		}
		id := BindingID{Key: k, Scope: p.ScopeID}
		if seen[id] {
			continue
		}
		seen[id] = true
		out = append(out, id)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Key != out[j].Key {
			return out[i].Key < out[j].Key
		}
		return out[i].Scope < out[j].Scope
	})
	return out
}

// providerAt finds the provider binding at exactly (key, scope). R1 fix: no
// "first record wins" — a wrong realm's record is a different binding.
func providerAt(o RuntimeSnapshot, key string, scope ScopeID) (ProviderView, bool) {
	for _, p := range o.Providers {
		if p.Key == key && p.ScopeID == scope {
			return p, true
		}
	}
	return ProviderView{}, false
}

// EquivalentValues is per-binding ≃ₖ (Def 31/32): agree on every field the
// key's OPERATIONS can observe.
func (m *ObservationModel) EquivalentValues(k CapabilityKey, a, b ProviderView) bool {
	if m != nil && m.invalid {
		return false // fail closed
	}
	f := m.fieldsFor(k)
	if f[ObserveAvailability] {
		if a.Retiring != b.Retiring || available(a) != available(b) {
			return false
		}
	}
	if f[ObserveOwnerGeneration] &&
		(a.OwnerFiberID != b.OwnerFiberID || a.OwnerActivationID != b.OwnerActivationID) {
		return false
	}
	if f[ObserveNamespace] && a.ScopeID != b.ScopeID {
		return false
	}
	return true
}

func available(p ProviderView) bool { return !p.Retiring && p.State == StateActive }

// EquivalentAt implements Definition 33 over ALL bindings in scope S (R1):
// domains (as (key,realm) sets) must match, and each binding's value must be
// ≃ₖ-related. An OBSERVER may further restrict which realms it can see via
// visibleScopes — nil means all realms; a non-nil map of key→scope restricts
// observation to a single realm per key (Def 33's S at realm granularity).
func (m *ObservationModel) EquivalentAt(a, b RuntimeSnapshot, S []CapabilityKey, visibleScopes map[CapabilityKey]ScopeID) bool {
	if m != nil && m.invalid {
		return false // fail closed
	}
	// Build a string-keyed view of the observer's realm restriction.
	vis := map[string]ScopeID{}
	for k, scope := range visibleScopes {
		vis[k.String()] = scope
	}
	// R1: observer-realm filtering must happen BEFORE domain comparison —
	// bindings in other realms are outside the observer's S and must not
	// affect either the domain set or the value comparison.
	ba := observableBindingsVisible(a, S, vis)
	bb := observableBindingsVisible(b, S, vis)
	if len(ba) != len(bb) {
		return false
	}
	for i := range ba {
		if ba[i] != bb[i] {
			return false
		}
		pa, oka := providerAt(a, ba[i].Key, ba[i].Scope)
		pb, okb := providerAt(b, bb[i].Key, bb[i].Scope)
		if oka != okb || !oka {
			return false
		}
		if !m.equivalentValuesString(ba[i].Key, pa, pb) {
			return false
		}
	}
	return true
}

// observableBindingsVisible enumerates bindings, dropping any whose realm is
// not the observer's for that key (Def 33 "forgets keys outside S", here at
// realm granularity). A superseded A-realm binding is invisible to a B-observer.
func observableBindingsVisible(o RuntimeSnapshot, S []CapabilityKey, vis map[string]ScopeID) []BindingID {
	all := ObservableBindings(o, S)
	if len(vis) == 0 {
		return all
	}
	out := all[:0]
	for _, id := range all {
		if want, ok := vis[id.Key]; ok && want != id.Scope {
			continue
		}
		out = append(out, id)
	}
	return out
}

// equivalentValuesString is EquivalentValues for a snapshot-string key.
func (m *ObservationModel) equivalentValuesString(k string, a, b ProviderView) bool {
	var ck CapabilityKey
	for declared := range m.ops {
		if declared.String() == k {
			ck = declared
			break
		}
	}
	f := m.fieldsFor(ck)
	if f[ObserveAvailability] && (a.Retiring != b.Retiring || available(a) != available(b)) {
		return false
	}
	if f[ObserveOwnerGeneration] &&
		(a.OwnerFiberID != b.OwnerFiberID || a.OwnerActivationID != b.OwnerActivationID) {
		return false
	}
	if f[ObserveNamespace] && a.ScopeID != b.ScopeID {
		return false
	}
	return true
}

// Preconditions are the paper's metatheory premises (Thm 64/68/70/73/80).
// ComputePreconditions derives them from a live snapshot (audit R4b).
type Preconditions struct {
	AcyclicPrecedence   bool
	ProviderUnique      bool
	PairwiseIndependent bool
	ComponentTotal      bool
}

func (p Preconditions) All() bool {
	return p.AcyclicPrecedence && p.ProviderUnique && p.PairwiseIndependent && p.ComponentTotal
}

func (p Preconditions) String() string {
	return fmt.Sprintf("acyclic=%v unique=%v independent=%v total=%v",
		p.AcyclicPrecedence, p.ProviderUnique, p.PairwiseIndependent, p.ComponentTotal)
}

// ComputePreconditions derives the paper's four metatheory premises FROM A
// LIVE RUNTIME SNAPSHOT (audit R4b) — not from hand-filled booleans:
//
//   - AcyclicPrecedence (Thm 73/80): the dependency graph has no cycle. We
//     check the identity-resolved consumer→provider edges recorded in the
//     snapshot for a cycle (a fiber transitively depending on itself).
//   - ProviderUnique (Thm 64/70): each (key, realm) binding has at most one
//     provider. ObservableBindings dedups by (key,scope); a duplicate record
//     in one binding is a violation.
//   - PairwiseIndependent (§3.4): operations at DISTINCT keys commute by
//     Thm 45; at ONE key the coeffect must carry a witness. The runtime
//     enforces per-key realm routing (Def 24) and per-key records, so the
//     snapshot-level check verifies no two bindings share a mutable record.
//   - ComponentTotal (Thm 80): every provider binding in the snapshot has a
//     live owner (Active, non-retiring) — no partial/stuck component.
func ComputePreconditions(snap RuntimeSnapshot) Preconditions {
	p := Preconditions{
		AcyclicPrecedence:   dependencyGraphAcyclic(snap),
		ProviderUnique:      bindingsUnique(snap),
		PairwiseIndependent: bindingsIndependent(snap),
		ComponentTotal:      componentsTotal(snap),
	}
	return p
}

// dependencyGraphAcyclic detects a cycle in the identity-resolved edges:
// consumer -> provider fiber. A cycle means Progress premises are violated.
func dependencyGraphAcyclic(snap RuntimeSnapshot) bool {
	edges := map[FiberID][]FiberID{}
	for _, d := range snap.Dependencies {
		if d.ConsumerFiberID == 0 || d.ProviderFiberID == 0 {
			continue
		}
		edges[d.ConsumerFiberID] = append(edges[d.ConsumerFiberID], d.ProviderFiberID)
	}
	state := map[FiberID]uint8{}
	var visit func(FiberID) bool
	visit = func(f FiberID) bool {
		if state[f] == 1 {
			return false // back edge
		}
		if state[f] == 2 {
			return true
		}
		state[f] = 1
		for _, next := range edges[f] {
			if !visit(next) {
				return false
			}
		}
		state[f] = 2
		return true
	}
	for f := range edges {
		if !visit(f) {
			return false
		}
	}
	return true
}

// bindingsUnique: at most one record per (key, realm) binding.
func bindingsUnique(snap RuntimeSnapshot) bool {
	seen := map[BindingID]bool{}
	for _, p := range snap.Providers {
		id := BindingID{Key: p.Key, Scope: p.ScopeID}
		if seen[id] {
			return false
		}
		seen[id] = true
	}
	return true
}

// bindingsIndependent is the SNAPSHOT-LEVEL precondition for §3.4: each
// provider binding must be a well-formed, separately-owned record (a non-empty
// key and a live owner identity). Actual COMMUTATION of operations at distinct
// keys is proven by EXECUTING them against the real runtime in
// independence_test.go (TestIndependenceRealRuntime*) — this structural check
// alone is not a proof of commutation and is not presented as one.
func bindingsIndependent(snap RuntimeSnapshot) bool {
	for _, p := range snap.Providers {
		if p.Key == "" || p.OwnerFiberID == 0 || p.OwnerActivationID == 0 {
			return false
		}
	}
	return true
}

// componentsTotal: every provided binding has a live, Active, non-retiring
// owner — no partial component in the quiescent state (Thm 80).
func componentsTotal(snap RuntimeSnapshot) bool {
	active := map[FiberID]bool{}
	for _, f := range snap.Fibers {
		if f.State == StateActive && f.ActivationID != 0 {
			active[f.ID] = true
		}
	}
	for _, p := range snap.Providers {
		if p.Retiring || !active[p.OwnerFiberID] {
			return false
		}
	}
	return true
}
